// Command dispatch in gsd-tools.cjs
switch (cmd) {
  case 'state':
    // Routes to state module functions
    break;
  case 'find-phase':
    phase.cmdFindPhase(cwd, args[1], raw);
    break;
  case 'resolve-model':
    config.cmdResolveModel(cwd, args[1], raw);
    break;
  case 'commit':
    commands.cmdCommit(cwd, args.slice(1), raw);
    break;
  default:
    error('Unknown command: ' + cmd);
}

// Sub-command dispatch for 'state'
case 'state': {
  const sub = args[1];
  switch (sub) {
    case 'load':
      state.cmdStateLoad(cwd, raw);
      break;
    case 'advance-plan':
      state.cmdAdvancePlan(cwd, raw);
      break;
    case 'add-decision':
      state.cmdAddDecision(cwd, args.slice(2), raw);
      break;
  }
  break;
}
